import { useState, useRef } from "react";
import StudentLayout from "./StudentLayout";

const ALL_SKILLS = [
  "React","Vue","Angular","Node.js","Express","Django","FastAPI",
  "Laravel","Python","Java","PHP","C++","SQL","PostgreSQL","MongoDB",
  "Docker","Git","Linux","Flutter","TypeScript","Redis","Kubernetes",
  "GraphQL","REST API","TensorFlow","Figma"
];
const WILAYAS = [
  "Alger","Oran","Constantine","Annaba","Béjaïa","Tizi Ouzou",
  "Blida","Sétif","Tlemcen","Batna","Bordj Bou Arréridj","Boumerdès","Tipaza","Médéa","Djelfa"
];
const LEVELS = ["A1","A2","B1","B2","C1","Native","Fluent","Professional"];

const GlobalStyles = () => (
  <style>{`
    @keyframes spin    { to{transform:rotate(360deg)} }
    @keyframes scale-in{ from{opacity:0;transform:scale(.92)} to{opacity:1;transform:scale(1)} }

    .anim-fade-up  { animation:fade-up .5s ease both; }
    .anim-scale-in { animation:scale-in .35s ease both; }
    .anim-d1 { animation-delay:.07s; }
    .anim-d2 { animation-delay:.14s; }

    .shimmer-btn {
      background:linear-gradient(90deg,#1A4A8A 0%,#2E7DF7 45%,#1A4A8A 100%);
      background-size:200% auto; animation:shimmer 3s linear infinite;
    }
    .shimmer-btn:hover { box-shadow:0 6px 20px rgba(46,125,247,.35); }

    .input-field {
      width:100%; padding:.7rem 1rem; border-radius:10px;
      border:1.5px solid #E2E8F0; font-family:'DM Sans',sans-serif;
      font-size:.875rem; color:#1C2B40; background:#F8FAFC; outline:none;
      transition:border-color .2s,box-shadow .2s,background .2s;
    }
    .input-field:focus { border-color:#2E7DF7; background:#fff; box-shadow:0 0 0 3px rgba(46,125,247,.1); }

    .card { background:#fff; border-radius:16px; border:1px solid #E8EDF5; }

    .badge { display:inline-flex; align-items:center; font-size:.7rem; font-weight:600; padding:.25rem .65rem; border-radius:100px; }
    .badge-blue  { background:#EBF2FF; color:#2563EB; }
    .badge-green { background:#ECFDF5; color:#059669; }
    .badge-slate { background:#F1F5F9; color:#475569; }

    .tab-btn {
      padding:.5rem 1rem; border-radius:8px; font-size:.82rem; font-weight:500;
      cursor:pointer; transition:all .18s; border:none; background:transparent;
      font-family:'DM Sans',sans-serif; display:flex; align-items:center; gap:.4rem;
    }
    .tab-btn.active   { background:#fff; color:#0B1F3A; box-shadow:0 1px 4px rgba(0,0,0,.1); }
    .tab-btn.inactive { color:#64748B; }

    .progress-bar-inner {
      height:100%; border-radius:100px;
      background:linear-gradient(90deg,#2E7DF7,#60A5FA); transition:width .6s ease;
    }

    .upload-zone {
      border:2px dashed #CBD5E1; border-radius:14px; padding:2rem; text-align:center; cursor:pointer; transition:all .22s; background:#F8FAFC;
    }
    .upload-zone:hover  { border-color:#2E7DF7; background:#EBF2FF; }
    .upload-zone.filled { border-color:#059669; border-style:solid; background:#ECFDF5; }
    .upload-zone.drag   { border-color:#2E7DF7; background:#EBF2FF; transform:scale(1.01); }
 ` }</style>
);

function calcCompletion(p) {
  let s = 0;
  if (p.firstName && p.lastName) s += 15;
  if (p.email)                   s += 10;
  if (p.phone)                   s += 5;
  if (p.university)              s += 10;
  if (p.wilaya)                  s += 5;
  if (p.bio)                     s += 15;
  if (p.skills.length >= 3)      s += 15;
  if (p.github)                  s += 15;
  if (p.digitalCV)               s += 10;
  return s;
}
